import sailpoint.connector.webservices.EndPoint;
 import sailpoint.object.ProvisioningPlan;
 import sailpoint.object.ProvisioningPlan.AccountRequest;
 import sailpoint.tools.Util;
 import java.util.List;


String nativeIdentity = null;

 if (provisioningPlan != null) {
   List accountRequests = provisioningPlan.getAccountRequests();
   if (accountRequests != null) {
     for (AccountRequest acctReq : accountRequests) {
       if (AccountRequest.Operation.Enable.equals(acctReq.getOperation())
           || AccountRequest.Operation.Modify.equals(acctReq.getOperation())) {
         nativeIdentity = acctReq.getNativeIdentity();
         break;
       }
     }
   }
 }

 if (Util.isNullOrEmpty(nativeIdentity) && requestEndPoint != null) {
   // Fallback: some flows expose the identity on the EndPoint context map.
   Object ni = requestEndPoint.getEndpointConfigMap() != null ? requestEndPoint.getEndpointConfigMap().get("nativeIdentity") : null;
   if (ni != null) {
     nativeIdentity = ni.toString();
   }
 }

 if (requestEndPoint != null && !Util.isNullOrEmpty(nativeIdentity)) {
   // Base URL is configured on the application (e.g. http://localhost:8081).
   String baseUrl = (String) application.getAttributeValue("genericWebServiceBaseUrl");
   if (Util.isNullOrEmpty(baseUrl)) {
     baseUrl = (String) application.getAttributeValue("baseUrl");
   }
   if (baseUrl != null && baseUrl.endsWith("/")) {
     baseUrl = baseUrl.substring(0, baseUrl.length() - 1);
   }

   String fullUrl = baseUrl + "/users/" + nativeIdentity + "/enable";

   requestEndPoint.setFullUrl(fullUrl);
   requestEndPoint.setHttpMethodType("PATCH");

   // No request body is required; the disable is driven by the URL path.
   requestEndPoint.setBody(null);

   if (log.isInfoEnabled()) {
     log.info("WebService Disable Account -> PATCH " + fullUrl);
   }
 }
